r"""
Crescopus - the CrescoGuide (conversational dispute summaries)

  - The AI dispute summary is now called the CrescoGuide.
  - The consent box says what's shared and with whom: "sent to Claude (by
    Anthropic), which powers the CrescoGuide".
  - The Privacy Policy now explains what's sent to Anthropic, and when.
  - Includes the earlier conversational-summary change. Run this whether or
    not you ran apply_ai_summary_text.py or apply_crescomediator.py.

HOW TO USE
  1. Save this file in your Crescopus project folder (next to wsgi.py).
  2. In PowerShell, in that folder, with your venv active:
         python apply_crescoguide.py
  3. No SQL to run.
  4. Any file it replaces is copied first to _backup_apply_crescoguide\.

It checks each file matches a version it knows first. If you've changed one
locally since your last push, it stops without writing anything.
Your .env is never read or changed.
"""
import base64, hashlib, os, shutil, sys

# (path, new content, sha256s of the versions it may replace)
FILES = [
    ('app/ledger/ai_summary.py', '', ['604a33417731032a38b41f3f26cbff2d0b1cfc0ddd939cc930440415b2c46000', '5cf086cb2c6f74749b6fc657b2f78e1a9de9baf673ea243b429bf0ed1ca36093', '94f192680789718dfe5a71a60a0f1ee1b9865db290196bf3d679f9bf1b63dffa']),
    ('app/ledger/disputes.py', '', ['b625469eeeef49451a544fe5d867698369704f0b03c4514a66c84b61a223989a', 'a829245e81500c606f6dc32061f9d4cc069e76d36445dd283e140edcaa84687d', '5e289a73e80f15f7b51fd37c433865326e4f38986823c377a8d32d8e7883b1ff']),
    ('app/templates/base.html', '', ['f308ccdda53cc75fb17171f5a08746ed9703412938e216998a4decc3bfde64b2', 'ca29aace12d50030d7dd5c8125d291a2510bb272b48881b05856a546100963a7']),
    ('app/templates/ledger/dispute_new.html', '', ['3dab95dc50bfcb5f4fb9ea01f69af54e5efa091d6263bb4742d76b2b33db925f', '82f27985adc122cc9531dd7bced479381122ab146e5503323f9c96bbec1f6171']),
    ('app/templates/ledger/dispute_view.html', '', ['ce8a72feb203116ff406d8bfab309381d066ae24fc914a7e0a0cca72cd068921', '0c275cfd0764879407a725c6b302c27e7de416cb0cdb3cb987ed14b2ba8127f8', '315e7bc212a233d46fc875fce0e239c11ab50e9404ac65937c35de5ef397911c']),
]
BACKUP = "_backup_apply_crescoguide"
NEXT = "restart python wsgi.py, open a dispute to check the CrescoGuide panel and an existing summary, then commit and push."

def sha(data):
    return hashlib.sha256(data).hexdigest()

def main():
    root = os.path.dirname(os.path.abspath(__file__))
    if not os.path.isfile(os.path.join(root, "app", "__init__.py")) or not os.path.isfile(os.path.join(root, "wsgi.py")):
        sys.exit("Stopped: put this file in the Crescopus project folder (next to wsgi.py and the app folder), then run it again.")

    # Safety check first: never overwrite local changes we don't know about.
    clashes = []
    for rel, b64, expected in FILES:
        path = os.path.join(root, *rel.split("/"))
        new = base64.b64decode(b64)
        if not os.path.exists(path):
            if expected:
                clashes.append(rel + " (missing)")
            continue
        with open(path, "rb") as fh:
            current = fh.read()
        current_norm = current.replace(b"\r\n", b"\n")
        if current == new or current_norm == new:
            continue
        if not expected or sha(current_norm) not in expected:
            clashes.append(rel)
    if clashes:
        print("Stopped - nothing written. These files differ from the version this update was built from:")
        for c in clashes:
            print("   " + c)
        sys.exit("Push or share your latest changes and ask for the update to be rebuilt.")

    backup = os.path.join(root, BACKUP)
    changed = 0
    for rel, b64, expected in FILES:
        path = os.path.join(root, *rel.split("/"))
        data = base64.b64decode(b64)
        status = "new     "
        if os.path.exists(path):
            with open(path, "rb") as fh:
                current = fh.read()
            if current == data or current.replace(b"\r\n", b"\n") == data:
                print("same     " + rel)
                continue
            dest = os.path.join(backup, *rel.split("/"))
            os.makedirs(os.path.dirname(dest), exist_ok=True)
            shutil.copy2(path, dest)
            status = "updated "
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "wb") as fh:
            fh.write(data)
        changed += 1
        print(status + " " + rel)
    print("\nDone - %d of %d files written." % (changed, len(FILES)))
    if os.path.isdir(backup):
        print("Originals of replaced files are in " + BACKUP + os.sep)
    if NEXT:
        print("Next: " + NEXT)

if __name__ == "__main__":
    main()
